class NoRedirect(urllib.request.HTTPRedirectHandler):
    def redirect_request(self, req, fp, code, msg, headers, newurl):
        return None


def make_opener(follow=True):
    ctx = ssl.create_default_context()
    ca = os.environ.get("SSL_CERT_FILE") or os.environ.get("REQUESTS_CA_BUNDLE")
    if ca and os.path.exists(ca):
        ctx.load_verify_locations(ca)
    handlers = [urllib.request.HTTPSHandler(context=ctx)]
    if not follow:
        handlers.append(NoRedirect())
    return urllib.request.build_opener(*handlers)


def _read(r, limit, t0):
    buf = bytearray()
    while len(buf) < limit:
        if time.time() - t0 > TIMEOUT * 2:
            raise TimeoutError("corpo da resposta demorou demais")
        b = r.read1(min(65536, limit - len(buf))) if hasattr(r, "read1") else r.read(min(65536, limit - len(buf)))
        if not b:
            break
        buf += b
    body = bytes(buf)
    if body[:2] == b"\x1f\x8b":
        try:
            body = gzip.decompress(body)
        except Exception:
            pass
    return body


def fetch(url, follow=True, limit=3_000_000, headers=None, method="GET"):
    if urllib.parse.urlparse(url).scheme not in ("http", "https"):
        return {"status": None, "url": url, "headers": None, "body": b"", "erro": "esquema não permitido", "ms": 0}
    h = {"User-Agent": UA, "Accept": "*/*"}
    h.update(headers or {})
    req = urllib.request.Request(url, headers=h, method=method)
    t0 = time.time()
    try:
        r = make_opener(follow).open(req, timeout=TIMEOUT)
        body = _read(r, limit, t0) if method != "HEAD" else b""
        return {"status": r.status, "url": r.geturl(), "headers": r.headers, "body": body, "ms": int((time.time() - t0) * 1000)}
    except urllib.error.HTTPError as e:
        try:
            body = e.read(limit) if method != "HEAD" else b""
        except Exception:
            body = b""
        return {"status": e.code, "url": url, "headers": e.headers, "body": body, "ms": int((time.time() - t0) * 1000)}
    except Exception as e:
        return {"status": None, "url": url, "headers": None, "body": b"", "erro": mask_secrets(f"{type(e).__name__}: {e}"),
                "ms": int((time.time() - t0) * 1000)}


class PageParser(HTMLParser):
    def __init__(self):
        super().__init__()
        self.scripts, self.http_refs, self.meta, self.links = [], [], {}, []
        self.title, self._in_title, self.html_lang = "", False, None

    def handle_starttag(self, tag, attrs):
        a = {k.lower(): (v or "") for k, v in attrs}
        if tag == "html":
            self.html_lang = a.get("lang")
        if tag == "title":
            self._in_title = True
        if tag == "script" and a.get("src"):
            self.scripts.append(a["src"])
        if tag == "link":
            self.links.append(a)
            if a.get("rel") in ("modulepreload", "preload") and a.get("href", "").endswith(".js"):
                self.scripts.append(a["href"])
        if tag == "meta":
            key = (a.get("name") or a.get("property") or "").lower()
            if key:
                self.meta[key] = a.get("content", "")
        for k in ("src", "href", "action"):
            v = a.get(k) or ""
            if v.startswith("http://") and tag in ("script", "img", "iframe", "link", "form", "video", "audio", "source"):
                self.http_refs.append(f"<{tag} {k}={v[:120]}>")

    def handle_endtag(self, tag):
        if tag == "title":
            self._in_title = False

    def handle_data(self, data):
        if self._in_title:
            self.title += data


def dns_txt(name, rtype="TXT"):
    """Consulta DNS por DNS-over-HTTPS (Cloudflare, depois Google). Retorna lista de respostas ou None se falhar."""
    for base in ("https://cloudflare-dns.com/dns-query", "https://dns.google/resolve"):
        url = f"{base}?name={urllib.parse.quote(name)}&type={rtype}"
        r = fetch(url, headers={"Accept": "application/dns-json"}, limit=200_000)
        if r["status"] == 200:
            try:
                data = json.loads(r["body"].decode("utf-8", "ignore"))
                if data.get("Status") not in (0, 3):
                    continue
                return [x.get("data", "").strip('"').replace('" "', "") for x in data.get("Answer", []) if x.get("data")]
            except Exception:
                continue
    return None


def cert_info(host):
    try:
        ctx = ssl.create_default_context()
        with socket.create_connection((host, 443), timeout=TIMEOUT) as sock:
            with ctx.wrap_socket(sock, server_hostname=host) as s:
                cert = s.getpeercert()
        exp = datetime.strptime(cert["notAfter"], "%b %d %H:%M:%S %Y %Z").replace(tzinfo=timezone.utc)
        issuer = dict(x[0] for x in cert.get("issuer", [])).get("organizationName", "")
        return {"expira_em": exp.date().isoformat(), "dias": (exp - datetime.now(timezone.utc)).days, "emissor": issuer}
    except Exception as e:
        return {"erro": f"{type(e).__name__}: {e}"}


def apex_of(host):
    parts = host.split(".")
    if len(parts) >= 3 and parts[-2] in ("com", "net", "org", "gov", "edu", "adv", "art", "blog", "eco", "app", "dev", "log", "med", "eng",
                                         "jus", "leg", "mp", "arq", "odo", "psi", "ind", "inf", "tur", "tv", "co", "ac", "nom") and len(parts[-1]) == 2:
        return ".".join(parts[-3:])
    return ".".join(parts[-2:])


# ---------------------------------------------------------------- sondagem opcional de dados públicos (só leitura)

def sondar_supabase(js_all, add, res):
    urls = sorted(set(re.findall(r"https://([a-z0-9]{20})\.supabase\.co", js_all)))
    anon = None
    for m in re.finditer(r"\beyJ[A-Za-z0-9_\-]{10,}\.eyJ[A-Za-z0-9_\-]{10,}\.[A-Za-z0-9_\-]{10,}", js_all):
        if (decode_jwt_payload(m.group(0)) or {}).get("role") == "anon":
            anon = m.group(0)
            break
    if not anon:
        pk = re.search(r"\bsb_publishable_[A-Za-z0-9_\-]{20,}", js_all)
        anon = pk.group(0) if pk else None
    if not urls or not anon:
        res["sondagem"]["supabase"] = {"nota": "projeto Supabase ou chave pública não encontrados no JavaScript público"}
        return
    ref = urls[0]
    tables = sorted(set(re.findall(r"\.from\(\s*['\"`]([A-Za-z0-9_]{1,63})['\"`]\s*\)", js_all)))[:40]
    out = {"projeto": ref, "tabelas_testadas": {}}
    auth = {"apikey": anon, "Authorization": f"Bearer {anon}"}
    for t in tables:
        # 1) prova barata: pede no máximo 1 linha e descarta o conteúdo (nada é impresso nem gravado)
        r = fetch(f"https://{ref}.supabase.co/rest/v1/{t}?select=*&limit=1", headers=auth, limit=200_000)
        visivel = False
        if r["status"] in (200, 206):
            try:
                visivel = len(json.loads((r["body"] or b"[]").decode("utf-8", "ignore"))) > 0
            except Exception:
                visivel = False
        total = None
        if visivel:  # 2) só na tabela exposta: contagem exata (o RLS vale para ela)
            c = fetch(f"https://{ref}.supabase.co/rest/v1/{t}?select=*", method="HEAD",
                      headers={**auth, "Prefer": "count=exact", "Range": "0-0"})
            cr = (c["headers"].get("content-range") if c.get("headers") else "") or ""
            total = cr.split("/")[-1] if "/" in cr else None
        out["tabelas_testadas"][t] = {"status": r["status"], "visivel_sem_login": visivel, "linhas": total}
        if visivel:
            add("C04", "supabase_tabela_legivel_sem_login", "alta",
                f"Tabela '{t}' devolve linhas para qualquer visitante ({total or '?'} no total), só com a chave pública do site — RLS ausente ou permissiva",
                f"{ref}.supabase.co/rest/v1/{t}")
    res["sondagem"]["supabase"] = out


def sondar_firebase(js_all, add, res):
    pid = re.search(r"projectId\s*:\s*['\"]([a-z0-9\-]{4,40})['\"]", js_all)
    if not pid:
        res["sondagem"]["firebase"] = {"nota": "projectId do Firebase não encontrado no JavaScript público"}
        return
    pid = pid.group(1)
    out = {"projeto": pid, "colecoes_testadas": {}}
    cols = sorted(set(re.findall(r"collection\(\s*\w+\s*,\s*['\"`]([A-Za-z0-9_\-]{1,60})['\"`]", js_all) +
                      re.findall(r"\.collection\(\s*['\"`]([A-Za-z0-9_\-]{1,60})['\"`]", js_all)))[:25]
    for c in cols:
        r = fetch(f"https://firestore.googleapis.com/v1/projects/{pid}/databases/(default)/documents/{c}?pageSize=1", limit=50_000)
        n = 0
        if r["status"] == 200:
            try:
                n = len(json.loads(r["body"].decode("utf-8", "ignore")).get("documents", []))
            except Exception:
                n = 0
        out["colecoes_testadas"][c] = {"status": r["status"], "documento_lido_sem_login": bool(n)}
        if n:
            add("C04", "firestore_colecao_publica", "alta", f"Coleção '{c}' do Firestore legível sem login (regras abertas)",
                f"firestore/{pid}/{c}")
    db = re.search(r"databaseURL\s*:\s*['\"](https://[a-z0-9\-]+\.(?:firebaseio\.com|firebasedatabase\.app))['\"]", js_all)
    if db:
        r = fetch(db.group(1) + "/.json?shallow=true", limit=50_000)
        out["realtime_db_status"] = r["status"]
        if r["status"] == 200:
            add("C04", "rtdb_publico", "alta", "Realtime Database lê a raiz sem login (\".read\": true)", db.group(1))
    bucket = re.search(r"storageBucket\s*:\s*['\"]([a-z0-9.\-]+)['\"]", js_all)
    if bucket:
        r = fetch(f"https://firebasestorage.googleapis.com/v0/b/{bucket.group(1)}/o?maxResults=1", limit=50_000)
        out["storage_lista_status"] = r["status"]
        if r["status"] == 200 and b'"items"' in (r["body"] or b""):
            add("C16", "storage_listavel", "alta", "Firebase Storage lista arquivos para qualquer visitante", bucket.group(1))
    res["sondagem"]["firebase"] = out


def main():
    ap = argparse.ArgumentParser(description=f"Checagem do site publicado · {CREDITO}")
    ap.add_argument("url")
    ap.add_argument("--out")
    ap.add_argument("--max-scripts", type=int, default=15)
    ap.add_argument("--sem-dns", action="store_true", help="não consulta SPF/DMARC/DKIM")
    ap.add_argument("--sondar-dados", action="store_true",
                    help="(só com OK do dono) pergunta ao Supabase/Firebase o que um visitante sem login lê — só leitura")
    args = ap.parse_args()

    url = args.url.strip()
    if not re.match(r"https?://", url):
        url = "https://" + url
    parsed = urllib.parse.urlparse(url)
    if parsed.username or parsed.password or "@" in parsed.netloc:
        sys.exit("Tire usuário e senha da URL: o check_url não usa credencial (e ela iria parar no relatório).")
    try:
        host = (parsed.hostname or "") + (f":{parsed.port}" if parsed.port else "")
    except ValueError:
        sys.exit("URL inválida (porta).")
    local = parsed.hostname in ("localhost", "127.0.0.1")
    plataforma = any((parsed.hostname or "").endswith("." + s) or parsed.hostname == s for s in PLATFORM_SUFFIXES)
    alt_host = (parsed.hostname[4:] if parsed.hostname.startswith("www.") else "www." + parsed.hostname) if parsed.hostname else ""

    def same_site(u):
        q = urllib.parse.urlparse(u)
        return q.scheme in ("http", "https") and (q.hostname or "").lower() in ((parsed.hostname or "").lower(), alt_host.lower())
    scheme = parsed.scheme if local else "https"
    base = f"{scheme}://{host}"
    res = {"ferramenta": f"check_url.py {VERSION}", "credito": CREDITO, "url": base, "achados": [], "headers": {}, "cookies": [],
           "probes": {}, "pagina": {}, "sondagem": {}}

    def add(check, rule, conf, note, evidence=""):
        res["achados"].append({"check": check, "regra": rule, "confianca": conf, "nota": note, "evidencia": evidence[:200]})

    main_r = fetch(base + (parsed.path or "/"), headers={"Accept-Encoding": "gzip, br", "Origin": "https://check-pre-lancamento.invalid"})
    if main_r["status"] is None:
        res["erro"] = main_r.get("erro")
        print(f"Não consegui acessar {base}: {main_r.get('erro')}")
        out(res, args)
        return
    if not same_site(main_r["url"]):
        res["erro"] = f"o site redirecionou para outro domínio ({urllib.parse.urlparse(main_r['url']).hostname}); análise interrompida"
        print(res["erro"] + ". Rode de novo com o endereço final, se ele também for seu.")
        out(res, args)
        return
    res["status"] = main_r["status"]
    res["url_final"] = main_r["url"]
    res["tempo_resposta_ms"] = main_r["ms"]
    h = main_r["headers"]
    res["headers"] = {k.lower(): ("[omitido]" if k.lower() == "set-cookie" else v) for k, v in h.items()}
    encoded = (h.get("content-encoding") or "").lower()
    if encoded:  # pedimos compressão só para medir; o conteúdo vem de novo sem compressão
        res["compressao"] = encoded
        main_r = fetch(base + (parsed.path or "/"))
    else:
        res["compressao"] = None

    # C18 headers
    present = {label: h.get(key) for key, label in SECURITY_HEADERS.items()}
    if not present["X-Frame-Options"] and "frame-ancestors" in (present["CSP"] or ""):
        present["X-Frame-Options"] = "(via CSP frame-ancestors)"
    res["security_headers"] = present
    missing = [k for k, v in present.items() if not v]
    if missing:
        add("C18", "headers_ausentes", "alta", "Headers ausentes na resposta real: " + ", ".join(missing))
    csp = present["CSP"] or ""
    if re.search(r"script-src[^;]*'unsafe-(inline|eval)'", csp) or (csp and "script-src" not in csp and re.search(r"default-src[^;]*'unsafe-inline'", csp)):
        add("C18", "csp_unsafe", "media", "CSP permite 'unsafe-inline'/'unsafe-eval' em scripts", csp[:200])
    for leak in ("x-powered-by", "server", "x-aspnet-version", "x-aspnetmvc-version", "x-generator"):
        v = h.get(leak)
        if v and (leak != "server" or re.search(r"\d", v)):
            add("C15" if leak != "server" else "C18", "header_revela_tecnologia", "baixa", f"{leak}: revela tecnologia/versão", f"{leak}: {v}")

    # C07 CORS refletindo qualquer origem
    acao = h.get("access-control-allow-origin")
    acac = (h.get("access-control-allow-credentials") or "").lower() == "true"
    if acao == "https://check-pre-lancamento.invalid":
        add("C07", "cors_reflete_origem", "alta" if acac else "media",
            "CORS devolve a origem que o visitante mandar" + (" COM credenciais: qualquer site lê dados logados" if acac else ""))
    elif acao == "*" and acac:
        add("C07", "cors_estrela_credenciais", "alta", "CORS * com Allow-Credentials: true")

    # C19 HTTPS + certificado
    if local:
        res["http_redirect"] = {"nota": "alvo local — checagem de HTTPS pulada"}
    else:
        check_https(res, fetch(f"http://{host}/", follow=False), host, add)
        res["certificado"] = cert_info(parsed.hostname)
        dias = res["certificado"].get("dias")
        if dias is not None and dias < 21:
            add("P05", "certificado_vencendo", "alta" if dias < 7 else "media", f"Certificado TLS vence em {dias} dia(s) — confira a renovação automática")
        alt = alt_host
        alt_r = fetch(f"https://{alt}/", follow=False, limit=20_000) if not plataforma else {"status": "pulado (domínio de plataforma)"}
        res["outra_variante"] = {"host": alt, "status": alt_r["status"], "final": alt_r.get("url")}
        if not plataforma and alt_r["status"] is None and parsed.hostname.count(".") <= 2:
            add("P08", "variante_www_fora_do_ar", "baixa", f"https://{alt} não responde — quem digitar a outra forma não chega ao site")
    hsts = present["HSTS"]
    if not hsts:
        add("C19", "sem_hsts", "media", "Sem Strict-Transport-Security")
    else:
        m = re.search(r"max-age=(\d+)", hsts)
        if m and int(m.group(1)) < 15552000:
            add("C19", "hsts_curto", "baixa", f"HSTS com max-age curto ({m.group(1)}s; recomendado ≥ 6 meses)")

    # C09 cookies
    for raw in h.get_all("set-cookie") or []:
        name = raw.split("=", 1)[0].strip()
        low = raw.lower()
        flags = {"secure": "; secure" in low or low.endswith("secure"), "httponly": "httponly" in low,
                 "samesite": (re.search(r"samesite=(\w+)", low) or [None, None])[1]}
        res["cookies"].append({"nome": name, **flags})
        sessionish = re.search(r"sess|auth|token|jwt|sid|connect\.sid|sb-|next-auth|__session|laravel_session|csrftoken", name, re.I)
        if sessionish and not flags["httponly"] and "csrf" not in name.lower() and "xsrf" not in name.lower():
            add("C09", "cookie_sem_httponly", "alta", f"Cookie de sessão '{name}' sem HttpOnly")
        if sessionish and not flags["secure"]:
            add("C09", "cookie_sem_secure", "alta", f"Cookie de sessão '{name}' sem Secure")
        if sessionish and flags["samesite"] == "none":
            add("C09", "cookie_samesite_none", "media", f"Cookie '{name}' com SameSite=None")

    # C15 arquivos que não deviam estar públicos
    home_body = main_r["body"][:200_000]
    for path, rx, note in PROBES:
        r = fetch(base + path, follow=False, limit=100_000)
        body = r["body"] or b""
        ok = r["status"] == 200 and body and body[:200_000] != home_body
        if ok and rx:
            ok = bool(re.search(rx, body.decode("utf-8", "ignore"), re.M))
        if ok and path == "/.DS_Store":
            ok = body[:8] == b"\x00\x00\x00\x01Bud1"
        if ok and path == "/actuator/heapdump":
            ok = body[:4] in (b"JAVA", b"\x1f\x8b\x08\x00") or b"PROFILE" in body[:64]
        res["probes"][path] = r["status"]
        if ok:
            check = "C17" if "graphql" in path else "C15"
            add(check, "arquivo_publico", "alta", note, base + path)
            if path.startswith("/.env"):
                add("C01", "env_publico", "alta", "Variáveis de ambiente acessíveis publicamente — rotacione tudo", base + path)

    # Página: SEO, compartilhamento e experiência (prontidão)
    html = main_r["body"].decode("utf-8", "ignore")
    p = PageParser()
    try:
        p.feed(html)
    except Exception:
        pass
    title = re.sub(r"\s+", " ", p.title).strip()
    desc = p.meta.get("description", "")
    res["pagina"] = {"titulo": title[:120], "descricao": desc[:200], "lang": p.html_lang, "og_title": p.meta.get("og:title"),
                     "og_image": p.meta.get("og:image"), "viewport": bool(p.meta.get("viewport")),
                     "favicon": any("icon" in (l.get("rel") or "") for l in p.links), "tamanho_html_kb": len(main_r["body"]) // 1024}
    if not title:
        add("P08", "sem_titulo", "media", "Página sem <title>")
    elif TEMPLATE_TITLE.match(title):
        add("P08", "titulo_padrao_de_template", "media", f"Título ainda é o do template: '{title}'")
    if not desc:
        add("P08", "sem_meta_description", "baixa", "Sem meta description (é o texto que aparece no Google)")
    if TEMPLATE_DESC.search(desc + " " + (p.meta.get("og:description") or "")) or "lovable.dev" in (p.meta.get("og:image") or ""):
        add("P08", "descricao_padrao_de_template", "media", "Descrição/imagem de compartilhamento ainda são as do template")
    if not p.meta.get("og:image"):
        add("P08", "sem_og_image", "baixa", "Sem og:image: link compartilhado no WhatsApp/LinkedIn sai sem imagem")
    if not p.meta.get("viewport"):
        add("P09", "sem_viewport", "media", "Sem meta viewport: no celular a página abre minúscula")
    robots_meta = (p.meta.get("robots") or "") + " " + (h.get("x-robots-tag") or "")
    if "noindex" in robots_meta.lower():
        add("P08", "noindex_em_producao", "alta", "A página pede para NÃO ser indexada (noindex) — o Google não vai mostrar o site")
    if p.html_lang and p.html_lang.lower().startswith("en") and re.search(r"[ãõçáéíóú]", title + desc + html[:20000], re.I):
        add("P08", "lang_en_em_site_pt", "baixa", f'<html lang="{p.html_lang}"> num site em português')
    if res["tempo_resposta_ms"] > 1800:
        add("P09", "resposta_lenta", "media", f"Página levou {res['tempo_resposta_ms']} ms para responder")
    if not res["compressao"] and len(main_r["body"]) > 30_000:
        add("P09", "sem_compressao", "baixa", "HTML sem compressão (gzip/br)")
    rb = fetch(base + "/robots.txt", limit=100_000)
    rtxt = rb["body"].decode("utf-8", "ignore") if rb["status"] == 200 else ""
    res["pagina"]["robots_txt"] = rb["status"]
    if rtxt and re.search(r"(?ims)User-agent:\s*\*\s*(?:\n\s*#[^\n]*)*\n\s*Disallow:\s*/\s*$", rtxt):
        add("P08", "robots_bloqueia_tudo", "alta", "robots.txt bloqueia o site inteiro (Disallow: /)", base + "/robots.txt")
    sm_url = (re.search(r"(?im)^\s*Sitemap:\s*(\S+)", rtxt) or [None, base + "/sitemap.xml"])[1]
    if not same_site(sm_url):
        sm_url = base + "/sitemap.xml"
    sm = fetch(sm_url, limit=200_000)
    res["pagina"]["sitemap"] = {"url": sm_url, "status": sm["status"]}
    if sm["status"] != 200 or b"<urlset" not in (sm["body"] or b"") and b"<sitemapindex" not in (sm["body"] or b""):
        add("P08", "sem_sitemap", "baixa", "Sem sitemap.xml válido", sm_url)
    rnd = "".join(random.choice(string.ascii_lowercase) for _ in range(10))
    nf = fetch(f"{base}/check-pre-lancamento-404-{rnd}", limit=50_000)
    res["pagina"]["status_pagina_inexistente"] = nf["status"]
    if nf["status"] == 200:
        add("P09", "soft_404", "baixa", "Página inexistente responde 200 (SPA sem 404 de verdade): o Google indexa páginas fantasma")

    # C01/C03/C15 bundles JS (+ cache dos assets)
    if p.http_refs:
        add("C19", "mixed_content", "media", "Recursos carregados via http:// na página", "; ".join(p.http_refs[:5]))
    scripts = []
    for s in p.scripts:
        full = urllib.parse.urljoin(main_r["url"], s)
        if urllib.parse.urlparse(full).netloc == urllib.parse.urlparse(main_r["url"]).netloc and full not in scripts:
            scripts.append(full)
    scripts = scripts[: args.max_scripts]
    res["scripts_analisados"] = scripts
    seen, maps_found, js_all, js_kb, no_cache = set(), 0, [], 0, 0
    for s in scripts:
        r = fetch(s, limit=6_000_000)
        if r["status"] != 200:
            continue
        cc = (r["headers"].get("cache-control") or "").lower() if r.get("headers") else ""
        if "max-age" not in cc and "immutable" not in cc:
            no_cache += 1
        js = r["body"].decode("utf-8", "ignore")
        js_kb += len(r["body"]) // 1024
        js_all.append(js)
        for ln in js.split("\n"):
            for chunk in (ln[i:i + 4000] for i in range(0, len(ln), 3800)):
                for pid, value, conf, desc_ in iter_secret_matches(chunk):
                    if pid in ("generic_assignment", "db_url_password") and conf != "alta":
                        continue
                    key = (pid, value)
                    if key in seen:
                        continue
                    seen.add(key)
                    if pid == "jwt":
                        if (decode_jwt_payload(value) or {}).get("role") == "service_role":
                            add("C03", "service_role_no_bundle", "alta", "JWT service_role no JavaScript público", f"{s} → {mask(value)}")
                        continue
                    if pid == "google_api_key":
                        add("C01", "google_key_no_bundle", "baixa", desc_, f"{s} → {mask(value)}")
                        continue
                    if pid == "supabase_secret":
                        add("C03", "sb_secret_no_bundle", "alta", "Chave sb_secret_ no JavaScript público", f"{s} → {mask(value)}")
                    add("C01", "segredo_no_bundle", "alta" if conf == "alta" else "media", f"{desc_} no JavaScript público", f"{s} → {mask(value)}")
        sm_ = re.search(r"//# sourceMappingURL=(\S+)", js[-2000:])
        map_url = urllib.parse.urljoin(s, sm_.group(1)) if sm_ and not sm_.group(1).startswith("data:") else s + ".map"
        if not same_site(map_url):
            continue
        mr = fetch(map_url, limit=200_000)
        if mr["status"] == 200 and b'"mappings"' in (mr["body"] or b""):
            maps_found += 1
            if maps_found == 1:
                add("C15", "source_map_publico", "media", "Source maps públicos (código-fonte original legível)", map_url)
    res["source_maps_publicos"] = maps_found
    res["pagina"]["javascript_kb"] = js_kb
    if js_kb > 1500:
        add("P09", "javascript_pesado", "media", f"{js_kb} KB de JavaScript na primeira página (lento em 4G)")
    if scripts and no_cache == len(scripts):
        add("P09", "assets_sem_cache", "baixa", "Arquivos JS sem Cache-Control de longa duração")

    # P06 DNS de e-mail
    if plataforma:
        res["dns_email"] = {"nota": "domínio da plataforma (vercel.app, lovable.app…): e-mail e DNS não são seus — use um domínio próprio para enviar e-mail"}
    elif not local and not args.sem_dns:
        apex = apex_of(parsed.hostname)
        txt = dns_txt(apex)
        if txt is None:  # DNS-over-HTTPS bloqueado: não insiste em dezenas de consultas
            res["dns_email"] = {"dominio": apex, "nota": "DNS-over-HTTPS indisponível (rede bloqueada?) — confira SPF, DKIM e DMARC manualmente"}
        else:
            spf = [t for t in txt if t.lower().startswith("v=spf1")]
            dmarc = [t for t in (dns_txt("_dmarc." + apex) or []) if t.lower().startswith("v=dmarc1")]
            mx = dns_txt(apex, "MX")
            dkim = [s_ for s_ in DKIM_SELECTORS if any("p=" in t for t in (dns_txt(f"{s_}._domainkey.{apex}") or []))]
            res["dns_email"] = {"dominio": apex, "spf": spf[:2], "dmarc": dmarc[:2], "mx": (mx or [])[:5], "dkim_seletores_achados": dkim}
            if not spf:
                add("P06", "sem_spf", "media", f"{apex} sem registro SPF: e-mail do domínio tende a cair no spam")
            if not dmarc:
                add("P06", "sem_dmarc", "media", f"{apex} sem DMARC (Gmail e Yahoo exigem para quem envia em volume)")
            elif re.search(r"\bp=none\b", dmarc[0]):
                add("P06", "dmarc_p_none", "baixa", "DMARC em p=none (só monitora): suba para quarantine quando estiver estável")
            if not dkim:
                res["dns_email"]["dkim_nota"] = "nenhum seletor comum achado — confira o seletor do seu provedor (Resend, SES, Google…)"

    # sondagem opcional de dados públicos
    if args.sondar_dados:
        blob = html + "\n".join(js_all)
        sondar_supabase(blob, add, res)
        sondar_firebase(blob, add, res)

    out(res, args)
    print_summary(res)


def check_https(res, http_r, host, add):
    loc = http_r["headers"].get("location") if http_r.get("headers") else None
    res["http_redirect"] = {"status": http_r["status"], "location": loc}
    if http_r["status"] in (301, 302, 303, 307, 308) and loc and loc.startswith("https://"):
        if http_r["status"] in (302, 303, 307):
            add("C19", "redirect_temporario", "baixa", f"HTTP redireciona para HTTPS com {http_r['status']} (prefira 301/308)")
    elif http_r["status"] is None:
        res["http_redirect"]["nota"] = "porta 80 não respondeu (ok se só HTTPS estiver aberto)"
    else:
        add("C19", "http_sem_redirect", "alta", f"http://{host} respondeu {http_r['status']} sem redirecionar para HTTPS")


def out(res, args):
    if args.out:
        os.makedirs(os.path.dirname(os.path.abspath(args.out)), exist_ok=True)
        with open(args.out, "w", encoding="utf-8") as fh:
            json.dump(res, fh, ensure_ascii=False, indent=2, default=str)


def print_summary(res):
    print(f"\n{banner()}")
    print(f"check_url · {res['url']} → {res.get('status')} ({res.get('url_final')}) em {res.get('tempo_resposta_ms')} ms")
    for k, v in res.get("security_headers", {}).items():
        print(f"  {'✔' if v else '✘'} {k}: {(v or '')[:90]}")
    print(f"  redirect http→https: {res.get('http_redirect')}")
    if res.get("certificado"):
        print(f"  certificado: {res['certificado']}")
    pg = res.get("pagina") or {}
    print(f"  página: título '{pg.get('titulo', '')}' · og:image {'✔' if pg.get('og_image') else '✘'} · viewport {'✔' if pg.get('viewport') else '✘'}"
          f" · JS {pg.get('javascript_kb', 0)} KB · 404 → {pg.get('status_pagina_inexistente')}")
    print(f"  bundles analisados: {len(res.get('scripts_analisados', []))} · source maps públicos: {res.get('source_maps_publicos', 0)}")
    if res.get("dns_email"):
        d = res["dns_email"]
        print(f"  e-mail ({d['dominio']}): SPF {'✔' if d['spf'] else '✘'} · DMARC {'✔' if d['dmarc'] else '✘'} · DKIM {', '.join(d['dkim_seletores_achados']) or '?'}")
    if res.get("sondagem"):
        print(f"  sondagem de dados públicos: {json.dumps(res['sondagem'], ensure_ascii=False)[:400]}")
    if res["achados"]:
        print("\nAchados:")
        for a in res["achados"]:
            print(f"  [{a['check']}] ({a['confianca']}) {a['nota']}" + (f" — {a['evidencia']}" if a["evidencia"] else ""))
    else:
        print("\nNenhum achado na checagem.")


if __name__ == "__main__":
    main()
